/* S1-02 — préparation de la collecte : validation d'entrée, couples NAF × département,
   bandes d'effectif D-008 (union). AUCUN appel réseau ici : le Code node de n8n 2.43.5
   (JsTaskRunner) n'a pas de fetch — l'appel HTTP est fait par le nœud « Collecte API ».
   Contrat : AGENTS.md §10 · ADR 0005 (siège) · D-002 (runs.details) · ADR 0006 (runs par campagne). */
/* S2-03 — état de collecte de CETTE exécution. La boucle par couple et par page le lit et l'écrit
   (elle ne peut pas transporter les pages dans un item : une panne remplacerait l'item par
   l'erreur). L'état est INDEXÉ par `$execution.id` : deux exécutions simultanées de WF1
   (deux campagnes dues, un run manuel pendant le tick) ne partagent donc rien, et l'état est
   supprimé quand les pages ont été rendues. */
const etatCollecte = $getWorkflowStaticData('global');
etatCollecte.collecte_s203 = etatCollecte.collecte_s203 || {};
const CLE_EXECUTION = String($execution.id || 'sans-id');

const campagne = $('Pour chaque campagne (S1-02)').first().json;
const runsRow  = $('Run démarré (campagne)').first().json;
const runId      = runsRow && typeof runsRow.id === 'string' ? runsRow.id : null;
const campaignId = campagne && typeof campagne.id === 'string' ? campagne.id : null;

/* 1) Tick à vide : l'item renvoyé par campaigns_due (alwaysOutputData) n'est pas une campagne. */

if (!campagne || typeof campagne.id !== 'string') {
  return [{ json: { run_id: runId, campaign_id: null, couple: false, vide: true, erreur: null,
    conservees: [], details: { recuperees: 0, ecartees: 0, bandes_appliquees: [] } } }];
}

/* 2) Validation d'entrée (critère du ticket) : aucun appel si aucun couple (code NAF × département). */
const nafCodes = Array.isArray(campagne.naf_codes) ? campagne.naf_codes.filter((c) => typeof c === 'string' && c.trim() !== '') : [];
const cibles   = Array.isArray(campagne.departements) ? campagne.departements.filter((d) => typeof d === 'string' && d.trim() !== '') : [];
if (nafCodes.length === 0 || cibles.length === 0) {
  return [{ json: { run_id: runId, campaign_id: campaignId, couple: false, vide: false,
    erreur: "campagne impossible à cibler : naf_codes ou departements vides — aucun appel API", conservees: [], details: null } }];
}

/* 3) Bandes d'effectif D-008 : la bande contenant effectif_min puis toutes les bandes supérieures,
      en UNION dans une seule requête. Bornes inf INSEE des 15 codes du vocabulaire figé. */
const codesBande  = ["00","01","02","03","11","12","21","22","31","32","41","42","51","52","53"];
const bornesBasse = [0, 1, 3, 6, 10, 20, 50, 100, 200, 250, 500, 1000, 2000, 5000, 10000];
const effectifMin = typeof campagne.effectif_min === 'number' && campagne.effectif_min > 0 ? campagne.effectif_min : null;
let bandesAppliquees = [];
if (effectifMin !== null) {
  let indice = 0;
  for (let i = 0; i < codesBande.length; i++) {
    if (bornesBasse[i] <= effectifMin) indice = i; else break;
  }
  bandesAppliquees = codesBande.slice(indice);
}

/* 4) Un item par couple (code NAF × département). S2-03 : les pages ne sont plus créées par la
      pagination native d'un nœud HTTP — c'est la boucle « Pour chaque couple » qui demande UNE page
      à la fois, ce qui rend une panne réparable page par page. */
const departementsCible = cibles.map((d) => d.trim().toLowerCase());
const items = [];
for (const nafCode of nafCodes) {
  for (const departement of departementsCible) {
    items.push({
      json: {
        couple: true, vide: false, erreur: null,
        run_id: runId,
        campaign_id: campaignId,
        naf: nafCode.trim(),
        departement: departement,
        departements_cible: departementsCible,
        naf_codes: nafCodes,
        bandes_appliquees: bandesAppliquees,
      },
    });
  }
}
/* 5) État de la collecte (S2-03), dans un bac propre à cette exécution : les couples DANS L'ORDRE, chacun avec sa page courante, ses
      pages acquises et son budget d'essais. C'est ce que la boucle par page alimente, et c'est
      de là que « Pages collectées » rend les pages au filtrage — un couple en échec y laisse
      une erreur nommée, jamais des pages tronquées présentées comme complètes. */
etatCollecte.collecte_s203[CLE_EXECUTION] = {
  courant: 0,
  couples: items.map((it) => ({
    naf: it.json.naf,
    departement: it.json.departement,
    bandes_appliquees: it.json.bandes_appliquees,
    page: 1,
    essais: 0,
    pages: [],
    refus: [],
    dernier_statut: null,
    attente_ms: null,
    erreur: null,
    fini: false,
  })),
};
for (let i = 0; i < items.length; i++) {
  items[i].json.idx = i;
  items[i].json.page = 1;
}
return items;

/* S1-02 · S1-04 · S2-02 — filtrage et compteurs sur les réponses de l'API (aucun réseau ici :
   le Code node de n8n n'a pas de fetch, cf. AGENTS.md §10).
   Entrée : les pages renvoyées par le nœud HTTP paginé (un item = le corps d'une page).
   Règles :
   - RATTACHEMENT (S2-02) : plus AUCUNE lecture de `pairedItem`. Mesuré le 2026-10-26 sur
     l'image de WF1 : pour un nœud qui rend PLUS d'items qu'il n'en reçoit, n8n range
     `{item: index de l'item d'entrée}` puis fait LIRE l'index de sortie — trois pages puis
     une page donnaient 0, 1, 2, 3 là où les couples étaient 0, 0, 0, 1. `outputPropertyName`
     ne peut pas porter la clé : il ne s'applique qu'aux réponses text/file et il est lu une
     seule fois, sur l'item 0. Le rattachement se fait donc sur la DONNÉE de chaque page :
     une page `page = 1` ouvre le segment du couple suivant, dans l'ordre de « Préparation de
     collecte » ; un segment se ferme sur une dernière page partielle (< 25 résultats) ou sur
     une erreur. Toute incohérence — numérotation, totaux, nombre de segments — est une
     ERREUR, jamais une attribution silencieuse.
   - anti-silence : chaque résultat porte le code NAF du couple ET etat_administratif = "A"
   - contrats de colonnes : `siren` (clé primaire) ET `name` (NOT NULL) vérifiés LOCALEMENT
   - plafond de pagination : un segment qui ne se ferme pas est une collecte tronquée
   - ADR 0005 : ne conserver que le siège ; compter les hors zone (jamais perdues)
   - D-002 : recuperees = renvoyées par l'API ; ecartees = écartées par la règle du siège
   - Continue on Fail : un couple en échec n'empêche pas les autres. S'il reste des données,
     le run écrit ce qu'il a et sort en `partial` ; s'il n'y en a aucune, il sort en `error`
     avec le message du couple fautif. Jamais de « succès » muet. */

const items = $input.all();
const couples = $('Préparation de collecte (S1-02)').all().map((it) => (it && it.json) || {});
const STATE_ERROR = "echec de collecte WF1 : ";
const TAILLE_PAGE = 25;

/* Le message d'un item en erreur n'a pas de forme unique : un délai dépassé porte
   `message` + `name`, une réponse HTTP en erreur porte `statusCode` + `error` (mesuré
   le 2026-10-26 : 500 → {statusCode, error}, timeout → {message}). On essaie dans
   l'ordre du plus informatif au plus générique, jamais un texte creux. */
function messageErreur(e) {
  if (e == null) return 'erreur inconnue';
  if (typeof e === 'string') return e.slice(0, 300);
  const parties = [];
  if (e.statusCode) parties.push('HTTP ' + e.statusCode);
  if (typeof e.error === 'string') parties.push(e.error.slice(0, 200));
  if (e.message) parties.push(String(e.message).slice(0, 200));
  if (e.description) parties.push(String(e.description).slice(0, 200));
  if (e.code && e.code !== e.statusCode) parties.push(String(e.code));
  if (parties.length === 0) parties.push(JSON.stringify(e).slice(0, 200));
  return parties.join(' — ').slice(0, 400);
}

/* ---- 1) Découpage en segments PAR LA DONNÉE de chaque page -------------------------- */

const segments = [];
const incoherences = [];
let courant = null;

for (const it of items) {
  const j = (it && it.json) || {};
  const enErreur = j.error != null;

  if (enErreur) {
    if (!courant || courant.ferme) { courant = { pages: [], erreurs: [], ferme: false }; segments.push(courant); }
    courant.erreurs.push(messageErreur(j.error));
    courant.ferme = true;
    continue;
  }

  if (j.page === 1) {
    if (courant && !courant.ferme) {
      incoherences.push("couple " + segments.length + " : page 1 reçue sans page partielle finale — la dernière page pleine (25 résultats) signale une dernière page manquante (plafond de pagination atteint ?)");
      courant.ferme = true;
    }
    courant = { pages: [], erreurs: [], ferme: false };
    segments.push(courant);
  }

  if (!courant) {
    incoherences.push("première page reçue sans page 1 : page " + JSON.stringify(j.page) + " — rattachement page/couple impossible");
    courant = { pages: [], erreurs: [], ferme: false };
    segments.push(courant);
  }

  const nb = Array.isArray(j.results) ? j.results.length : -1;
  courant.pages.push({ page: j, nb });
  if (nb < TAILLE_PAGE) courant.ferme = true;   /* dernière page partielle (ou corps illisible) */
}

/* ---- 2) Contrôles globaux : un segment par couple, contexte identique partout ------- */

if (segments.length !== couples.length) {
  incoherences.push(segments.length + " segment(s) de pages pour " + couples.length + " couple(s) — le rattachement page/couple n'est pas vérifiable");
}

const contexteCouple = couples[0] || {};
const memeContexte = couples.every((c) => c.run_id === contexteCouple.run_id
  && c.campaign_id === contexteCouple.campaign_id
  && JSON.stringify(c.departements_cible || []) === JSON.stringify(contexteCouple.departements_cible || [])
  && JSON.stringify(c.bandes_appliquees || []) === JSON.stringify(contexteCouple.bandes_appliquees || []));
if (!memeContexte) {
  incoherences.push("les couples ne portent pas le même contexte de campagne (run_id / campaign_id / departements_cible / bandes) — attribution impossible");
}

const details = { recuperees: 0, ecartees: 0, bandes_appliquees: Array.isArray(contexteCouple.bandes_appliquees) ? contexteCouple.bandes_appliquees : [] };
const base = { run_id: contexteCouple.run_id || null, campaign_id: contexteCouple.campaign_id || null };
const departementsCible = Array.isArray(contexteCouple.departements_cible) ? contexteCouple.departements_cible : [];
const conservees = [];
const messagesEchec = [];

/* Un rattachement que l'on ne sait pas vérifier est un échec : mieux vaut ne rien écrire que
   d'écrire des lignes attribuées au mauvais couple. */
if (incoherences.length > 0) {
  return [{ json: { ...base, couple: false, vide: false, conservees: [], details, echecs_collecte: incoherences.length,
    erreur: (STATE_ERROR + incoherences.length + " incohérence(s) de rattachement des pages — collecte interrompue : " + incoherences.join(' || ')).slice(0, 900) } }];
}

/* ---- 3) Un couple par segment, dans l'ordre de « Préparation de collecte » ---------- */

for (let i = 0; i < segments.length; i++) {
  const seg = segments[i];
  const couple = couples[i] || {};
  const cle = (typeof couple.naf === 'string' ? couple.naf : '?') + '|' + (typeof couple.departement === 'string' ? couple.departement : '?');

  if (seg.erreurs.length > 0) {
    messagesEchec.push(cle + " : " + seg.erreurs.join(' / ').slice(0, 300));
    continue;                       /* Continue on Fail : ce couple ne bloque pas les autres */
  }
  if (seg.pages.length === 0) { messagesEchec.push(cle + " : aucune page reçue"); continue; }
  if (!seg.ferme) {
    messagesEchec.push(cle + " : derniere page pleine (25 resultats) — collecte tronquee (100 pages max) ou volume anormal a arbitrer");
    continue;
  }

  const nafDemande = typeof couple.naf === 'string' ? couple.naf.trim() : null;
  if (!nafDemande) { messagesEchec.push(cle + " : code NAF du couple introuvable"); continue; }

  let erreurCouple = null;
  let vus = 0;
  const totalAnnonce = seg.pages[0].page.total_results;
  for (let p = 0; p < seg.pages.length; p++) {
    const { page, nb } = seg.pages[p];
    if (page.page !== p + 1) {
      erreurCouple = "pages hors sequence : page " + JSON.stringify(page.page) + " en position " + (p + 1) + " — rattachement non verifiable";
      break;
    }
    if (page.total_results !== totalAnnonce) {
      erreurCouple = "total_results variable dans le couple (" + JSON.stringify(totalAnnonce) + " puis " + JSON.stringify(page.total_results) + ") — la pagination de ce couple n'est pas coherente";
      break;
    }
    vus += nb;
  }
  if (!erreurCouple && vus !== totalAnnonce) {
    erreurCouple = vus + " resultats recus pour " + JSON.stringify(totalAnnonce) + " annonces par l'API — collecte incomplete";
  }
  if (erreurCouple) { messagesEchec.push(cle + " : " + erreurCouple); continue; }

  for (const { page } of seg.pages) {
    const resultats = Array.isArray(page.results) ? page.results : [];
    for (const resultat of resultats) {
      if (resultat.activite_principale !== nafDemande) {
        erreurCouple = "verification anti-silence : activite_principale = " + JSON.stringify(resultat.activite_principale) + " au lieu de " + nafDemande;
        break;
      }
      if (resultat.etat_administratif !== 'A') {
        erreurCouple = "verification anti-silence : etat_administratif = " + JSON.stringify(resultat.etat_administratif) + " (demande A)";
        break;
      }
      if (typeof resultat.siren !== 'string' || resultat.siren.trim() === '') {
        erreurCouple = "contrat : entreprise sans siren, siren=" + JSON.stringify(resultat.siren);
        break;
      }
      const nomEntreprise = resultat.denomination_unite_legale || resultat.denomination || resultat.nom_complet || resultat.nom_raison_sociale || null;
      if (typeof nomEntreprise !== 'string' || nomEntreprise.trim() === '') {
        erreurCouple = "contrat : entreprise sans name (denomination/nom_complet absents), siren=" + JSON.stringify(resultat.siren);
        break;
      }
      details.recuperees++;
      const siege = resultat.siege || null;
      const deptSiege = siege && typeof siege.departement === 'string' ? siege.departement.toLowerCase() : null;
      if (deptSiege && departementsCible.includes(deptSiege)) {
        conservees.push({
          siren: resultat.siren,
          name: nomEntreprise,
          naf: resultat.activite_principale || null,
          address: siege.adresse || null,
          city: siege.libelle_commune || null,
          postal_code: siege.code_postal || null,
          effectif: typeof resultat.tranche_effectif_salarie === 'string' ? resultat.tranche_effectif_salarie : null,
          campaign_id: base.campaign_id,
          raw: resultat,
          run_id: base.run_id,
        });
      } else {
        details.ecartees++;
      }
    }
    if (erreurCouple) break;
  }
  if (erreurCouple) messagesEchec.push(cle + " : " + erreurCouple);
}

const nbEchecs = messagesEchec.length;
const messageEchec = nbEchecs > 0 ? (nbEchecs + " couple(s) en echec — " + messagesEchec.join(' || ').slice(0, 900)) : null;

/* Aucune donnée : s'il y a un échec, le run part en ERREUR (jamais un « succès » muet). */
if (conservees.length === 0) {
  if (nbEchecs > 0) {
    return [{ json: { ...base, couple: false, vide: false, conservees: [], details, echecs_collecte: nbEchecs, erreur: messageEchec } }];
  }
  /* Réponse vide = cas nominal (département valide × NAF valide sans résultat) → success, 0 écrit. */
  return [{ json: { ...base, couple: false, vide: true, erreur: null, conservees: [], details, echecs_collecte: 0, message_echec: null } }];
}

/* Des données ET des couples en échec : on écrit ce qu'on a, le run sortira `partial`. */
return conservees.map((ligne) => ({
  json: { ...ligne, couple: false, vide: false, erreur: null, conservees: null, details, echecs_collecte: nbEchecs, message_echec: messageEchec },
}));

/* S1-03 — construction du LOT d'entreprises à upsert (aucun réseau ici — AGENTS.md §10).
   Contrats :
   - ADR 0007 : l'écriture est un SEUL POST PostgREST atomique ?on_conflict=siren
     + Prefer: resolution=merge-duplicates ; le lot est dédoublonné ICI, avant le POST,
     pour ne jamais toucher la garde PostgREST (« cannot affect row a second time »).
   - D-010 : doublon de SIREN intra-lot (couple multi-départements) → le PREMIER item
     gagne ; les suivants sont rejetés et comptés (jamais perdus).
   - D-009 : campaign_id n'est PAS dans le payload d'upsert (la passe de propriété,
     distincte, attribue les lignes fraîches après le POST — cf. ADR 0007, point 3).
   - Critère S1-03 : les colonnes enrichies (website, email, phone, website_source)
     ne sont jamais envoyées — absentes du payload, pas « écrasées à null ».
   Sortie : UNE item = UN lot (payload `lot` + contexte de conciliation). */
const items = $input.all();
const source = $('Filtrage et compteurs (S1-02)').first();
const base = source && source.json ? source.json : {};
const COLONNES_PAYLOAD = ['siren', 'name', 'naf', 'address', 'city', 'postal_code', 'effectif', 'raw'];
const lot = [];
const vus = new Set();
let entrees = 0;
let doublons_rejetes = 0;
for (const it of items) {
  const j = (it && it.json) || {};
  if (typeof j.siren !== 'string' || j.siren.trim() === '') continue;
  entrees++;
  if (vus.has(j.siren)) { doublons_rejetes++; continue; }
  vus.add(j.siren);
  const ligne = {};
  for (const c of COLONNES_PAYLOAD) ligne[c] = j[c] ?? null;
  lot.push(ligne);
}
const details = base.details ?? { recuperees: 0, ecartees: 0, bandes_appliquees: [] };
return [{ json: { ...base, details, entrees, doublons_rejetes, log: 'lot sirens=' + vus.size + ' entrees=' + entrees + ' doublons=' + doublons_rejetes, lot } }];

/* S1-03 — passe de propriété (ADR 0007 point 3, D-009) : attribue la campagne aux
   lignes NOUVELLES seulement. Les SIREN viennent du LOT lui-même (pas de la réponse
   du POST : forme d'items n8n non garantie) — le filtre `campaign_id=is.null` du PATCH
   suffit à ne toucher que les lignes fraîches : une ligne déjà attribuée (au re-passage
   ou par une autre campagne) n'est JAMAIS re-attribuée, et aucune autre colonne n'est
   touchée. Aucun réseau ici. Sortie : UNE item { urlAttribution, corps, ...base }. */
const lotItem = $('Lot des entreprises (S1-03)').first();
const base = lotItem && lotItem.json ? lotItem.json : {};
const lot = Array.isArray(base.lot) ? base.lot : [];
const sirens = [];
const vus = new Set();
for (const ligne of lot) {
  const s = ligne && typeof ligne.siren === 'string' ? ligne.siren : null;
  if (s && !vus.has(s)) { vus.add(s); sirens.push(s); }
}
const campagneId = base.campaign_id;
if (!campagneId) { throw new Error("garde attribution : campaign_id absent du lot — passe de propriété annulée"); }
const urlProjet = base.url ? base.url : 'https://rexnoeixlkedvdhzeoqk.supabase.co';
const liste = sirens.map((s) => '"' + s + '"').join(',');
const urlAttribution = urlProjet + '/rest/v1/companies?campaign_id=is.null&siren=in.(' + liste + ')';
const corps = { campaign_id: campagneId };
return [{ json: { ...base, attribution: { sirens: sirens.length }, urlAttribution, corps } }];

/* S1-03 · S1-04 — conciliation de la chaîne d'écriture.
   Entrée : la sortie du nœud PATCH (alwaysOutputData : un item même si rien n'a été attribué) ;
   un item porte `error` si la chaîne d'écriture a échoué.
   D-002 : `items_processed` = lignes RÉELLEMENT écrites = taille du lot (POST atomique).
   S1-04 : les ÉCHECS DE COLLECTE comptent aussi — un couple en panne, invisibles sinon,
   faisait sortir le run en `success` alors que sa collecte était incomplète. */
const items = $input.all();
const lotItem = $('Lot des entreprises (S1-03)').first();
const base = lotItem && lotItem.json ? lotItem.json : {};
const lot = Array.isArray(base.lot) ? base.lot : [];
const echecsEcriture = items.filter((it) => it.json && it.json.error != null);
const echecsCollecte = Number(base.echecs_collecte) || 0;
const total = echecsEcriture.length + echecsCollecte;
const messages = [];
if (echecsCollecte > 0) messages.push(base.message_echec || (echecsCollecte + " couple(s) en echec de collecte (message absent)"));
if (echecsEcriture.length > 0) messages.push(echecsEcriture.length + " echec(s) sur la chaine d'ecriture (le POST du lot est atomique : un echec annule tout le lot)");
return [{
  json: {
    run_id: base.run_id ?? null,
    campaign_id: base.campaign_id ?? null,
    details: base.details ?? { recuperees: 0, ecartees: 0, bandes_appliquees: [] },
    statut: total > 0 ? 'partial' : 'success',
    ecrites: lot.length,
    echecs: total,
    message_echec: messages.length > 0 ? messages.join(' || ').slice(0, 900) : null,
  },
}];

/* S1-03 — conciliation du chemin d'échec : le POST du lot a échoué (UN item
   d'erreur — AGENTS.md §10). Rien n'a été écrit (POST atomique : 0 lignes).
   D-002 : `items_processed` = 0 ; statut = partial ; l'erreur est conservée. */
const items = $input.all();
const lotItem = $('Lot des entreprises (S1-03)').first();
const base = lotItem && lotItem.json ? lotItem.json : {};
const echec = items.find((it) => it.json && it.json.error != null);
const message = echec && echec.json.error ? (typeof echec.json.error === 'string' ? echec.json.error : String(JSON.stringify(echec.json.error)).slice(0, 300)) : 'échec du POST du lot (subception)';
return [{
  json: { ...base, statut: 'partial', ecrites: 0, echecs: 1, error: message },
}];

/* S2-03 — après CHAQUE requête d'une page : garder ce que l'API a servi, et décider quoi faire.
   La décision est écrite UNE fois, ici, et elle ne dépend que de la réponse :
   - page servie et partielle (< 25 résultats) → le couple est terminé
   - page servie et pleine → page suivante du même couple
   - refus passager (429, 408, 5xx, panne réseau) → nouvelle tentative de CETTE page, après
     retry-after annoncé + 1 s (et jamais moins de 5 000 ms) : le `retry-after` est un PLANCHER,
     jamais un objectif — la marge couvre un réveil du nœud Wait mesuré jusqu'à ~0,9 s trop tôt
   - refus métier (4xx hors 408/429), budget d'essais épuisé, ou attente demandée > 60 s → abandon
     du couple, NOMMÉ. Les pages acquises ne sont pas écrites pour autant : un couple tronqué
     présenté comme complet serait un succès muet, exactement ce que S1-04 interdit.
   Mesuré le 2026-10-28 (stub, mêmes conditions) : refus page 3 → 6 requêtes pour 5 pages avec ce
   mécanisme, contre 9 avec le réessai d'item, et les 5 pages conservées au lieu de 0.
   Aucun appel réseau ici (le Code node de n8n n'a pas de fetch, AGENTS.md §10). */

const etat = ($getWorkflowStaticData('global').collecte_s203 || {})[String($execution.id || 'sans-id')];
if (!etat || !Array.isArray(etat.couples) || etat.couples.length === 0) {
  throw new Error("S2-03 : état de collecte absent — la boucle a été atteinte sans « Préparation de collecte (S1-02) »");
}
const couple = etat.couples[etat.courant];
if (!couple) {
  throw new Error("S2-03 : aucun couple en cours (index " + etat.courant + ") — boucle désynchronisée");
}

const TAILLE_PAGE = 25;
const MAX_PAGES = 100;              /* même plafond que maxRequests de S1-04 */
const MAX_ESSAIS_PAR_PAGE = 5;      /* 1 requête + 4 reprises AU PLUS par page */
const ATTENTE_MIN_MS = 5000;        /* plancher de politesse : jamais plus rapproché */
const ATTENTE_MARGE_MS = 1000;      /* mesuré : le Wait de n8n 2.43.5 s'est réveillé jusqu'à 931 ms
                                       avant l'échéance demandée (4 069 ms pour 5 000 demandés) —
                                       sans marge, le plancher de l'API ne tiendrait pas */
const ATTENTE_MAX_MS = 60000;       /* au-delà, on abandonne au lieu d'attendre moins que demandé */

const reponse = $json || {};
const erreurNoeud = reponse.error != null ? reponse.error : null;
const statut = typeof reponse.statusCode === 'number'
  ? reponse.statusCode
  : (erreurNoeud && typeof erreurNoeud.statusCode === 'number' ? erreurNoeud.statusCode : null);
const enEchec = erreurNoeud !== null || (statut !== null && statut >= 400);

/* Corps d'une réponse réussie : fullResponse renvoie { body, headers, statusCode } ; on garde le
   corps à plat, comme le faisait la pagination native, pour que le filtrage le lise à l'identique. */
const corps = !enEchec && reponse.body && typeof reponse.body === 'object' ? reponse.body : reponse;

function retryAfterMs(brut) {
  if (brut == null) return null;
  const texte = String(brut).trim();
  if (/^\d+$/.test(texte)) return Number(texte) * 1000;          /* secondes */
  const date = Date.parse(texte);                                  /* forme date HTTP */
  if (!Number.isNaN(date)) return Math.max(0, date - Date.now());
  return null;
}

function lireRetryAfter(rep, err) {
  const sources = [rep.headers, rep.response && rep.response.headers,
                   err && err.response && err.response.headers, err && err.headers];
  for (const entetes of sources) {
    if (!entetes || typeof entetes !== 'object') continue;
    const cle = Object.keys(entetes).find((k) => k.toLowerCase() === 'retry-after');
    if (cle !== undefined) {
      const ms = retryAfterMs(entetes[cle]);
      if (ms !== null) return ms;
    }
  }
  return null;
}

function messageErreur(e, st) {
  const parties = [];
  if (st !== null && st !== undefined) parties.push('HTTP ' + st);
  if (e && typeof e === 'object') {
    if (typeof e.error === 'string') parties.push(e.error.slice(0, 200));
    if (typeof e.erreur === 'string') parties.push(e.erreur.slice(0, 200));   /* corps de l'API, en français */
    if (e.message) parties.push(String(e.message).slice(0, 200));
    if (parties.length === 0) parties.push(JSON.stringify(e).slice(0, 200));
  } else if (e != null) {
    parties.push(String(e).slice(0, 200));
  }
  return parties.join(' — ').slice(0, 400) || 'erreur inconnue';
}

let etape;

if (!enEchec && Array.isArray(corps.results)) {
  couple.pages.push({ ...corps, statusCode: statut === null ? 200 : statut });
  couple.essais = 0;
  couple.attente_ms = null;
  etat.reprise_apres_ms = null;
  couple.dernier_statut = statut === null ? 200 : statut;
  if (corps.results.length < TAILLE_PAGE) couple.fini = true;              /* dernière page */
  else if (couple.pages.length >= MAX_PAGES) couple.fini = true;            /* plafond S1-04 */
  else couple.page += 1;
  etape = couple.fini ? 'fini' : 'page';
} else if (!enEchec) {
  couple.dernier_statut = statut;
  couple.erreur = "réponse sans tableau « results » à la page " + couple.page + " — contrat de l’API non respecté";
  couple.fini = true;
  etape = 'fini';
} else {
  const statutEchec = statut;
  const attenteApi = lireRetryAfter(reponse, erreurNoeud);
  const corpsErreur = reponse.body && typeof reponse.body === 'object' ? reponse.body : null;
  const message = messageErreur(erreurNoeud || corpsErreur, statutEchec);
  couple.dernier_statut = statutEchec;
  couple.refus.push({ statut: statutEchec, retry_after_ms: attenteApi, message });
  const metier = statutEchec !== null && statutEchec >= 400 && statutEchec < 500
    && statutEchec !== 408 && statutEchec !== 429;
  const demandee = attenteApi !== null ? attenteApi : ATTENTE_MIN_MS;
  if (metier) {
    couple.erreur = "refus définitif de l’API à la page " + couple.page + " : " + message;
    couple.fini = true;
    etape = 'fini';
  } else if (couple.essais + 1 >= MAX_ESSAIS_PAR_PAGE) {
    couple.erreur = couple.essais + 1 + " tentative(s) sur la page " + couple.page
      + " sans réponse exploitable (" + message + ") — couple abandonné";
    couple.fini = true;
    etape = 'fini';
  } else if (demandee > ATTENTE_MAX_MS) {
    couple.erreur = "l’API demande une attente de " + Math.round(demandee / 1000) + " s (retry-after), au-delà de la limite de "
      + Math.round(ATTENTE_MAX_MS / 1000) + " s — nouvelle tentative abandonnée plutôt que trop rapprochée";
    couple.fini = true;
    etape = 'fini';
  } else {
    couple.essais += 1;
    couple.attente_ms = Math.max(demandee + ATTENTE_MARGE_MS, ATTENTE_MIN_MS);
    /* Échéance, pas durée : la garde de rythme peut ainsi revérifier plusieurs fois sans jamais
       reprolonger l'attente (mesuré : une durée réappliquée à chaque tour bouclait sans fin). */
    etat.reprise_apres_ms = Date.now() + couple.attente_ms;
    etape = 'reessai';
  }
}

/* Horodatage de la dernière requête : c'est lui qui tient la cadence de S1-04 (1 req/s), et non le
   minuteur du nœud Wait — mesuré, ce dernier rend la main avant l'échéance demandée. */
etat.dernier_appel_ms = Date.now();

return {
  json: {
    etape,
    attente_api_ms: etape === 'reessai' ? couple.attente_ms : null,
    idx: etat.courant,
    page: couple.page,
    naf: couple.naf,
    departement: couple.departement,
    bandes_appliquees: couple.bandes_appliquees,
    pages_recues: couple.pages.length,
    essais: couple.essais,
  },
};

/* S1-04 · S2-03 — tenir la cadence « 1 requête par seconde » AVANT chaque appel.
   Pourquoi ce nœud existe : le minuteur du nœud Wait de n8n rend la main avant l'échéance demandée
   (mesuré le 2026-10-28 : 474 ms et 799 ms pour 1 000 ms demandés, 4 069 ms pour 5 000). Confier la
   politesse de crawl à ce seul minuteur, c'est publier une garantie que la mesure démentit. On calcule
   donc l'attente depuis l'HORODATAGE de la dernière requête, et on revérifie au retour du Wait :
   chaque passage ne peut que rapprocher de l'échéance, donc la boucle se termine.

   Deux planchers, et on garde le plus grand :
   - la cadence de S1-04 : 1 000 ms entre deux requêtes, mesurée sur l'horloge, pas sur un minuteur ;
   - le délai demandé par l'API après un refus (attente_api_ms, déjà calculé dans « Accumuler la
     page » : retry-after + 1 s, jamais moins de 5 s). */
const etat = ($getWorkflowStaticData('global').collecte_s203 || {})[String($execution.id || 'sans-id')];
if (!etat) throw new Error("S2-03 : état de collecte absent dans « Rythme de la requête »");

const CADENCE_MS = 1000;
const dernier = typeof etat.dernier_appel_ms === 'number' ? etat.dernier_appel_ms : null;
const ecoule = dernier === null ? CADENCE_MS : Date.now() - dernier;
const resteCadence = Math.max(0, CADENCE_MS - ecoule);
const echeance = typeof etat.reprise_apres_ms === 'number' ? etat.reprise_apres_ms : 0;
const resteApi = Math.max(0, echeance - Date.now());
const attente = Math.max(resteCadence, resteApi);

return {
  json: {
    ...$json,
    attente_ms: attente,
    attendre: attente > 1,          /* 1 ms de tolérance : sous ce seuil, on n'attend pas */
    ecoule_ms: ecoule,
    reste_cadence_ms: resteCadence,
    reste_api_ms: resteApi,
  },
};

/* S2-03 — le couple a fini (collecté, ou abandonné avec son erreur) : on passe au suivant.
   Les pages vivent dans l'état du tick ; ce nœud ne fait qu'avancer le curseur et dire s'il reste
   un couple — la boucle suivante est pilotée par cette réponse, pas par le « done » implicite. */
const etat = ($getWorkflowStaticData('global').collecte_s203 || {})[String($execution.id || 'sans-id')];
if (!etat || !Array.isArray(etat.couples) || etat.couples.length === 0) {
  throw new Error("S2-03 : état de collecte absent — la boucle a été atteinte sans « Préparation de collecte (S1-02) »");
}
const courant = etat.couples[etat.courant];
if (!courant) {
  throw new Error("S2-03 : aucun couple en cours (index " + etat.courant + ") — boucle désynchronisée");
}
etat.courant += 1;
return {
  json: {
    reste: etat.courant < etat.couples.length,
    couple_termine: { naf: courant.naf, departement: courant.departement,
                      pages: courant.pages.length, erreur: courant.erreur, refus: courant.refus.length },
  },
};

/* S2-03 — rendre au filtrage les pages collectées, DANS L'ORDRE des couples de « Préparation de
   collecte » : un item par page, exactement la forme que produisait la pagination native, pour que
   « Filtrage et compteurs » et le rattachement par la donnée de S2-02 n'aient rien à changer.
   Un couple abandonné rend UN item en erreur (le filtrage le nomme et continue les autres) —
   jamais ses pages tronquées : un couple incomplet serait un succès muet. */
const etat = ($getWorkflowStaticData('global').collecte_s203 || {})[String($execution.id || 'sans-id')];
if (!etat || !Array.isArray(etat.couples)) {
  throw new Error("S2-03 : état de collecte absent au moment de rendre les pages");
}

const sortie = [];
for (const couple of etat.couples) {
  if (couple.erreur) {
    sortie.push({ json: { error: { statusCode: couple.dernier_statut, message: couple.erreur } } });
    continue;
  }
  if (!Array.isArray(couple.pages) || couple.pages.length === 0) {
    sortie.push({ json: { error: { statusCode: null, message: "aucune page reçue" } } });
    continue;
  }
  for (const page of couple.pages) sortie.push({ json: page });
}
if (sortie.length === 0) {
  sortie.push({ json: { error: { statusCode: null, message: "aucune page collectée" } } });
}

/* L'état de cette exécution a fait son office : on le retire, pour qu'un tick ne laisse jamais
   traîner les pages d'un autre. */
delete $getWorkflowStaticData('global').collecte_s203[String($execution.id || 'sans-id')];
return sortie;
